import { type SynapseEnhancedHttpClient } from "../utils/http.ts";
import { ErrorCode } from "../utils/error-codes.ts";
import { EnhancedApi } from "../constants/api.ts";
import type { IBlockedUser } from "../models/types.ts";
import { handleApiResponse } from "../utils/response-formatter.ts";
import { BaseApi } from "../utils/base-api.ts";

export class FriendsBlockApi extends BaseApi {
    public constructor(httpClient: SynapseEnhancedHttpClient) {
        super(httpClient);
    }

    public async getBlockedUsers(): Promise<IBlockedUser[]> {
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                blocked_users?: Array<{ user_id: string; reason?: string; blocked_at?: string }>;
                total?: number;
            };
            error?: string;
        }>(EnhancedApi.FRIENDS_BLOCKED_LIST);

        const data = handleApiResponse(response, "Failed to get blocked users");

        const blockedUsers = data.blocked_users || [];
        return blockedUsers.map((user) => ({
            user_id: user.user_id,
            display_name: undefined,
            reason: user.reason,
            blocked_at: user.blocked_at,
        }));
    }

    public async blockUser(targetId: string, reason?: string): Promise<boolean> {
        if (!targetId || typeof targetId !== "string") {
            throw this.createError("Invalid target ID", ErrorCode.INVALID_PARAM);
        }

        const response = await this.httpClient.post<{
            status: string;
            error?: string;
        }>(EnhancedApi.FRIENDS_BLOCK, { user_id: targetId, reason });

        handleApiResponse(response, "Failed to block user");
        return true;
    }

    public async unblockUser(targetId: string): Promise<boolean> {
        if (!targetId || typeof targetId !== "string") {
            throw this.createError("Invalid target ID", ErrorCode.INVALID_PARAM);
        }

        const response = await this.httpClient.delete<{
            status: string;
            error?: string;
        }>(EnhancedApi.FRIENDS_UNBLOCK.replace("{userId}", encodeURIComponent(targetId)));

        handleApiResponse(response, "Failed to unblock user");
        return true;
    }

    public async isBlocked(userId: string): Promise<boolean> {
        if (!userId || typeof userId !== "string") {
            throw this.createError("Invalid user ID", ErrorCode.INVALID_PARAM);
        }

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                is_blocked?: boolean;
            };
            error?: string;
        }>(EnhancedApi.FRIENDS_BLOCKED_CHECK.replace("{userId}", encodeURIComponent(userId)));

        const data = handleApiResponse(response, "Failed to check if user is blocked");
        return data.is_blocked || false;
    }
}
